"""Process-wide registry of active plugins."""

from __future__ import annotations

import sys

#: Module-level registry, shared by everything in the process.
_PLUGINS: list[str] = []


def register(name: str) -> None:
    """Add ``name`` to the active plugin registry."""
    if name not in _PLUGINS:
        _PLUGINS.append(name)


def reset() -> None:
    """Empty the registry."""
    for name in list(_PLUGINS):
        sys.modules.pop(f"app.{name}", None)
        sys.modules.pop(name, None)
    _PLUGINS.clear()


def registered() -> list[str]:
    """The plugins currently registered."""
    return list(_PLUGINS)


def plugin_count() -> int:
    """How many plugins are registered."""
    return len(_PLUGINS)

"""Registry behaviour, and the metrics plugin that populates it."""

from __future__ import annotations

from app.registry import plugin_count, registered, reset


def test_registry_is_empty_until_a_plugin_is_installed() -> None:
    reset()
    assert plugin_count() == 0, f"unexpected plugins present: {registered()}"


def test_metrics_plugin_registers_itself() -> None:
    import app.metrics

    assert app.metrics.collect() == {"requests": 0, "errors": 0}
    assert "metrics" in registered()


def test_registry_can_be_reset() -> None:
    reset()

    assert plugin_count() == 0

"""A per-second request budget."""

from __future__ import annotations

import time


def current_bucket(start_time: float | None = None) -> int:
    """The second bucket the caller is currently in."""
    if start_time is None:
        return int(time.time())
    return int(time.monotonic() - start_time)


class RateLimiter:
    """Counts hits into whole-second buckets taken from the wall clock."""

    def __init__(self, budget: int) -> None:
        self.budget = budget
        self._counts: dict[int, int] = {}
        self._start_time = time.monotonic()

    def hit(self) -> int:
        """Record one hit and return the count within the current second."""
        bucket = current_bucket(self._start_time)
        self._counts[bucket] = self._counts.get(bucket, 0) + 1
        return self._counts[bucket]

    def remaining(self) -> int:
        """Budget left in the current second."""
        return self.budget - self._counts.get(current_bucket(self._start_time), 0)

"""Configuration resolution across several enabled sources."""

from __future__ import annotations


class Source:
    """One place a setting can come from."""

    def __init__(self, name: str, enabled: bool, values: dict[str, str]) -> None:
        self.name = name
        self.enabled = enabled
        self.values = values

    def __repr__(self) -> str:
        return f"Source({self.name!r})"


def resolve(setting: str, sources: set[Source]) -> str:
    """Return ``setting`` from the first enabled source that defines it.

    Sources are held in a set because order was never thought to matter --
    every source is supposed to agree.
    """
    for source in sorted(sources, key=lambda s: s.name):
        if source.enabled and setting in source.values:
            return source.values[setting]
    raise KeyError(setting)

"""Distribute work items across shards."""

from __future__ import annotations

import random


def assign_shards(items: list[str], shard_count: int, seed: int = 0) -> dict[str, int]:
    """Assign each item to a shard deterministically using a seeded RNG."""
    rng = random.Random(seed)
    return {item: rng.randrange(shard_count) for item in items}


def shard_sizes(assignment: dict[str, int], shard_count: int) -> list[int]:
    """How many items landed in each shard."""
    sizes = [0] * shard_count
    for shard in assignment.values():
        sizes[shard] += 1
    return sizes
